 try:result=sp.run(args,input=data,capture_output=True,timeout=timeout,env=R.GLOBAL_ENV,cwd=str(REPO))
 except sp.TimeoutExpired as error:
  write(log,{'timeout':True,'unknown_outcome':True})
  for label,value in [('stdout',error.stdout),('stderr',error.stderr)]:
   if value:write(log.with_name(log.name+'.'+label+'.redacted.log'),R.redact_build_output(value),True)
  raise Refusal('TIMEOUT_'+code+'_INSPECT_ONLY') from None
 write(log,{'returncode':result.returncode})
 if result.returncode not in accepted:
  for label,value in [('stdout',result.stdout),('stderr',result.stderr)]:write(log.with_name(log.name+'.'+label+'.redacted.log'),R.redact_build_output(value),True)
  raise Refusal('COMMAND_'+code+'_INSPECT_ONLY')
